CREATE TABLE "pos_expiry_plans" ("id" TEXT PRIMARY KEY, "shopkeeperId" TEXT NOT NULL REFERENCES "shopkeeper_profiles"("id") ON DELETE CASCADE, "batchId" TEXT NOT NULL, "action" TEXT NOT NULL, "quantity" DECIMAL(14,3) NOT NULL CHECK("quantity">0), "target" TEXT NOT NULL, "note" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PLANNED', "resolution" TEXT, "completedAt" TIMESTAMP(3), "actorUserId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
